import{F as e,_ as t,f as n,h as r,j as i,n as a}from"./chunks/shared.rYHlazZf.js";var o=JSON.parse(`{"title":"Instale e gerencie plugins","description":"","frontmatter":{"title":"Instale e gerencie plugins","docId":"user.plugins.index","translationKey":"user.plugins.index","locale":"pt","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"2892162f1f2ec94f8e5072f6689382b3c32c8546f2ad667a4651c721f597e84a","translationRevision":"cda0c046066dd02aacd2d623830fed749f55fb2d300ae481928ddb525d8abd5b","order":10},"headers":[],"relativePath":"pt/user/plugins/index.md","filePath":"pt/user/plugins/index.md","lastUpdated":1795731074000}`),s={name:`pt/user/plugins/index.md`};function c(a,o,s,c,l,u){let d=e(`TourFrame`);return i(),n(`div`,null,[o[0]||=r(`<h1 id="install-and-manage-plugins" tabindex="-1">Instale e gerencie plugins <a class="header-anchor" href="#install-and-manage-plugins" aria-label="Permalink to “Instale e gerencie plugins”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Objetivo e pré-requisitos”">​</a></h2><p>Adicione uma integração, revise o acesso solicitado e confirme que suas ações podem ser usadas. Você precisa de um pacote de desktop compatível com o sistema operacional, a arquitetura e a versão de host do plugin. Operações de catálogo remoto e download exigem acesso à rede; alguns serviços baseados em conta também exigem <a href="./../cloud/account.html">login no Cloud</a>.</p><h2 id="review-before-enabling" tabindex="-1">Revise antes de ativar <a class="header-anchor" href="#review-before-enabling" aria-label="Permalink to “Revise antes de ativar”">​</a></h2><ol><li>Abra <strong>Plugins</strong> e inspecione Installed, Explore ou Updates. Explore solicita apenas itens de plugins. Encontre modelos de automação e perfis em <a href="./../automations/templates.html">Automations</a>.</li><li>Selecione um plugin para inspecionar descrição, versão, compatibilidade e ambiente de execução. Confira o publicador e as capacidades ou permissões solicitadas, em vez de confiar apenas em um nome de exibição conhecido.</li><li>Use o fluxo de instalação para inspecionar a prévia do pacote. Revise a versão exata, informações de assinatura, acesso solicitado e alterações em relação à versão instalada antes de confirmar a instalação.</li><li>Aguarde o resultado da tarefa do pacote. Baixar, instalar e ativar são etapas distintas; um cartão de catálogo sozinho não significa que o ambiente de execução está pronto.</li><li>Abra o painel Settings ou Connection do plugin. Forneça o endereço do serviço e as credenciais apenas nos campos destinados a isso. Use uma verificação de conexão declarada quando disponível.</li><li>Ative o plugin e confira se seus tipos de ação ou páginas aparecem. Crie uma <a href="./../automations/first-rule.html">regra de registro</a> com escopo restrito antes de associar uma ação externa poderosa.</li></ol><p>Plugins podem executar código nativo ou processos separados. Um limite de processo pode isolar uma falha, mas não é uma sandbox do sistema operacional. Instale software de publicadores em quem confia. Uma assinatura válida identifica a procedência revisada do pacote; não torna todo efeito adequado ao seu fluxo.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Resultado esperado e status”">​</a></h2><p>Revisão de pacotes, tarefas de instalação, preferências de plugins e gerenciamento de versões estão disponíveis. As ações reais dependem do manifesto instalado, das capacidades do host e do serviço externo. Processadores de eventos têm seu próprio painel e podem adicionar campos opcionais de análise aos eventos; os campos brutos permanecem distintos.</p><h2 id="recovery" tabindex="-1">Recuperação <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recuperação”">​</a></h2><p>Para uma falha de instalação, leia o erro da tarefa para problemas de compatibilidade, assinatura, ambiente de execução ou download. Não enfraqueça a verificação apenas para eliminar um erro. Se uma atualização causar problemas, inspecione as versões mantidas e use a reversão quando disponível. Revise automações dependentes antes de desativar ou desinstalar um plugin. Mantenha <a href="./../preferences/backups.html">backups</a> dos dados e configurações de plugins antes de removê-los.</p>`,10),t(d,{id:`plugin`,locale:`pt`,title:`Demonstração: plugins`}),o[1]||=r(`<h2 id="command-line-operations" tabindex="-1">Operações de linha de comando <a class="header-anchor" href="#command-line-operations" aria-label="Permalink to “Operações de linha de comando”">​</a></h2><p>Cada operação deste guia também está disponível na CLI — offline, scriptável e apta para agentes. As linhas de uso são sintaxe do parser e permanecem em inglês em todos os idiomas.</p><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools plugin list</code></td><td>listar os plugins instalados</td></tr><tr><td><code>tiktools plugin get &lt;id&gt;</code></td><td>ler um plugin</td></tr><tr><td><code>tiktools plugin install &lt;file.plugin&gt; [--replace] &amp;#124; plugin install &lt;id[@version]&amp;#124;url&gt; [--yes] [--no-wait] [--allow-unsigned]</code></td><td>instalar a partir de um arquivo, id@version ou url</td></tr><tr><td><code>tiktools plugin uninstall &lt;id&gt; [--purge]</code></td><td>desinstalar um plugin <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin search &lt;query&gt; [--category c] [--page N]</code></td><td>buscar pacotes no registro</td></tr><tr><td><code>tiktools plugin inspect &lt;spec&gt;</code></td><td>inspecionar uma especificação de pacote antes de instalar</td></tr><tr><td><code>tiktools plugin outdated</code></td><td>listar os plugins instalados com atualizações disponíveis</td></tr><tr><td><code>tiktools plugin update &lt;id&gt; [--version v] [--yes] [--no-wait]</code></td><td>atualizar um plugin</td></tr><tr><td><code>tiktools plugin update --all [--yes] [--no-wait]</code></td><td>atualizar todos os plugins desatualizados</td></tr><tr><td><code>tiktools plugin rollback &lt;id&gt; [version] [--no-wait]</code></td><td>voltar a uma versão anterior <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin versions &lt;id&gt;</code></td><td>listar as versões disponíveis de um plugin</td></tr><tr><td><code>tiktools plugin pin &lt;id&gt;</code></td><td>fixar um plugin na sua versão atual</td></tr><tr><td><code>tiktools plugin unpin &lt;id&gt;</code></td><td>remover a fixação de versão</td></tr><tr><td><code>tiktools plugin policy &lt;id&gt; [--channel stable&amp;#124;beta] [--auto off&amp;#124;notify&amp;#124;patch&amp;#124;minor]</code></td><td>definir o canal e a política de atualização automática</td></tr><tr><td><code>tiktools plugin jobs</code></td><td>listar os trabalhos de pacotes</td></tr><tr><td><code>tiktools plugin job &lt;job-id&gt;</code></td><td>inspecionar um trabalho de pacote</td></tr><tr><td><code>tiktools plugin cancel &lt;job-id&gt;</code></td><td>cancelar um trabalho de pacote em andamento <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin enable &lt;id&gt;</code></td><td>ativar um plugin</td></tr><tr><td><code>tiktools plugin disable &lt;id&gt;</code></td><td>desativar um plugin</td></tr><tr><td><code>tiktools plugin start &lt;id&gt;</code></td><td>iniciar um plugin</td></tr><tr><td><code>tiktools plugin stop &lt;id&gt;</code></td><td>parar um plugin <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin settings get &lt;id&gt;</code></td><td>ler a configuração de um plugin</td></tr><tr><td><code>tiktools plugin settings set &lt;id&gt; k=v...</code></td><td>escrever a configuração de um plugin</td></tr><tr><td><code>tiktools plugin settings reset &lt;id&gt;</code></td><td>redefinir a configuração de um plugin <strong>destrutivo</strong></td></tr><tr><td><code>tiktools plugin health &lt;id&gt;</code></td><td>verificação de saúde de um plugin</td></tr><tr><td><code>tiktools plugin options &lt;action-type/field&gt;</code></td><td>opções de um tipo de ação ou campo</td></tr><tr><td><code>tiktools plugin action &lt;type&gt; [--config json] [--live]</code></td><td>executar uma ação de plugin</td></tr><tr><td><code>tiktools plugin commands</code></td><td>listar os comandos contribuídos pelos plugins instalados</td></tr><tr><td><code>tiktools plugin help [id]</code></td><td>descrever um comando contribuído</td></tr><tr><td><code>tiktools plugin &lt;id&gt; &lt;command&gt; [--params json] [--live]</code></td><td>invocar um comando contribuído por um plugin</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools registry list</code></td><td>listar os registros configurados</td></tr><tr><td><code>tiktools registry refresh</code></td><td>atualizar os metadados do registro</td></tr><tr><td><code>tiktools registry package &lt;id&gt;</code></td><td>mostrar um pacote do registro</td></tr><tr><td><code>tiktools registry cloud-catalog [--query q] [--after cursor] [--generation value] [--target name]</code></td><td>buscar no catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-summaries [--query q] [--cursor value] [--generation value] [--target name]</code></td><td>página de resumos do catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-versions &lt;id&gt; [--target name] [--generation value] [--cursor value]</code></td><td>versões de um pacote do catálogo cloud</td></tr><tr><td><code>tiktools registry cloud-pagination</code></td><td>capacidades de paginação do catálogo cloud</td></tr><tr><td><code>tiktools registry defaults</code></td><td>configuração padrão do registro</td></tr></tbody></table><table tabindex="0"><thead><tr><th>Comando</th><th>Resumo</th></tr></thead><tbody><tr><td><code>tiktools processor list</code></td><td>listar os processadores</td></tr><tr><td><code>tiktools processor status</code></td><td>estado do pipeline de processadores</td></tr><tr><td><code>tiktools processor test &lt;plugin-id&gt; &lt;processor-id&gt; [event-json]</code></td><td>executar um processador contra um evento de amostra</td></tr></tbody></table><p>Consulte a <a href="./../../developer/cli.html">referência completa de comandos</a> para as convenções, a saída JSON e os marcadores de operações destrutivas.</p>`,6)])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};